'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var isMatrixLike = require( '@stdlib/assert/is-matrix-like' );
var isVectorLike = require( '@stdlib/assert/is-vector-like' );
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var format = require( '@stdlib/string/format' );
var isObject = require( '@stdlib/assert/is-object' );
var dcopy = require( '@stdlib/blas/base/dcopy' );
var closestPrototype = require( './find_closest_proto.js' );
var squaredEuclidean = require( './squared_euclidean.js' );
var createIntVector = require( './int_vector.js' );
var copyVector = require( './copy_vector.js' );
var updatePrototype = require( './update_proto.js' );
var createMatrix = require( './matrix.js' );
var copyMatrix = require( './copy_matrix.js' );
var validate = require( './validate.js' );
var addPrototype = require( './add_proto.js' );


// FUNCTIONS //

/**
* Gets the label at a given index from a labels vector.
*
* @private
* @param {ndarray} labels - labels vector
* @param {NonNegativeInteger} idx - index
* @returns {NonNegativeInteger} label value
*/
function getLabel( labels, idx ) {
	return labels.data[ labels.offset + ( idx * labels.strides[ 0 ] ) ];
}

/**
* Checks if a label exists in the labels vector.
*
* @private
* @param {ndarray} labels - labels vector
* @param {NonNegativeInteger} label - label to search for
* @param {PositiveInteger} len - number of labels
* @returns {boolean} whether label exists
*/
function hasLabel( labels, label, len ) {
	var i;
	for ( i = 0; i < len; i++ ) {
		if ( getLabel( labels, i ) === label ) {
			return true;
		}
	}
	return false;
}

/**
* Returns a results object.
*
* @private
* @param {PositiveInteger} k - number of prototypes
* @param {PositiveInteger} ndims - number of dimensions
* @returns {Object} results object
*/
function createResults( k, ndims ) {
	var out = {};
	out.prototypes = createMatrix( k, ndims, false ); // high-level
	out.labels = createIntVector( k, false ); // high-level
	return out;
}


// MAIN //

/**
* Returns an accumulator function which incrementally performs supervised classification using lvq1.
*
* @param {ndarray|Options} [prototypes] - a `k x ndims` matrix containing initial prototypes
* @param {ndarray} [labels] - a vector of length `k` containing prototype labels (integers)
* @param {Options} [options] - function options
* @param {string} [options.metric="euclidean"] - distance metric
* @param {PositiveNumber} [options.learningRate=0.1] - initial learning rate
* @throws {TypeError} second argument must be a vector if first argument is a matrix
* @throws {TypeError} labels vector length must match number of prototypes
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {Function} accumulator function
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* // Define initial prototype locations (2 prototypes, 2 dimensions):
* var buffer = new Float64Array( [ 0.0, 0.0, 1.0, 1.0 ] );
* var prototypes = ndarray( 'float64', buffer, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
*
* // Define prototype labels:
* var labelBuffer = new Int32Array( [ 0, 1 ] );
* var labels = ndarray( 'int32', labelBuffer, [ 2 ], [ 1 ], 0, 'row-major' );
*
* // Create an LVQ accumulator:
* var accumulator = incrlvq( prototypes, labels );
*
* var out = accumulator();
* // returns {...}
*
* // Create a data vector:
* var vecBuffer = new Float64Array( 2 );
* var vec = ndarray( 'float64', vecBuffer, [ 2 ], [ 1 ], 0, 'row-major' );
*
* // Provide labeled data to the accumulator:
* vec.set( 0, 0.5 );
* vec.set( 1, 0.5 );
*
* out = accumulator( vec, 0 ); // data point with label 0
* // returns {...}
*/
function incrlvq( ) {
	var protoLabels;
	var options;
	var results;
	var protos;
	var ndims;
	var opts;
	var dist;

	var FLG;
	var err;
	var k;

	opts = {
		'metric': 'euclidean',
		'learningRate': 0.1
	};

	if ( isMatrixLike( arguments[ 0 ] ) ) {
		if ( !isVectorLike( arguments[ 1 ] ) ) {
			throw new TypeError( format( 'invalid argument. Second argument must be a vector containing prototype labels if prototypes are passed. Value: `%s`.', arguments[ 1 ] ) );
		}

		k = arguments[ 0 ].shape[ 0 ];
		ndims = arguments[ 0 ].shape[ 1 ];

		if ( arguments[ 1 ].shape[ 0 ] !== k ) {
			throw new TypeError( format( 'invalid argument. Labels vector length must match number of prototypes. Expected: `%u`. Actual: `%u`.', k, arguments[ 1 ].shape[ 0 ] ) );
		}

		protos = createMatrix( k, ndims, true ); // low-level
		protos = copyMatrix( protos, arguments[ 0 ] );

		protoLabels = createIntVector( k, true ); // low-level
		protoLabels = copyVector( protoLabels, arguments[ 1 ] );
		if ( arguments.length > 2 ) {
			options = arguments[ 2 ];
			FLG = true;
		}
	} else if ( isObject( arguments[ 0 ] ) ) {
		if ( arguments.length > 1 ) {
			throw new TypeError( format( 'invalid argument. First argument must be a matrix containing initial prototypes. Value: `%s`.', arguments[ 0 ] ) );
		}
		options = arguments[ 0 ];
		FLG = true;
	} else if ( arguments.length !== 0 ) {
		throw new TypeError( format( 'invalid argument. Arguments must either be prototypes, labels and options or just options. Value: `%s`.', arguments ) );
	}

	if ( FLG ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
	}
	if ( opts.metric === 'euclidean' ) {
		dist = squaredEuclidean;
	}
	if ( protos ) {
		results = createResults( k, ndims );
		copyMatrix( results.prototypes, protos );
		copyVector( results.labels, protoLabels );
	} else {
		// No prototype initialized
		k = 0;
	}

	setReadOnly( accumulator, 'predict', predict );

	return accumulator;

	/**
	* If provided a data point vector and label, the accumulator function returns updated results. If not provided arguments, the accumulator function returns the current results.
	*
	* @private
	* @param {ndarray} [vec] - data vector
	* @param {integer} [y] - target class label
	* @throws {TypeError} first argument must be a 1-dimensional ndarray
	* @throws {TypeError} second argument must be an integer (class label)
	* @throws {Error} vector length must match prototype dimensions
	* @returns {(Object|null)} classification results or null
	*/
	function accumulator( vec, y ) {
		var newData;
		var mini;
		var pbuf;
		var vbuf;
		var sp;
		var op;
		var sv;
		var ov;
		var lr;

		if ( arguments.length === 0 ) {
			if ( k === 0 ) {
				return null;
			}
			return results;
		}
		if ( arguments.length < 2 ) {
			throw new TypeError( format( 'invalid invocation. Must provide both a data vector and a class label.' ) );
		}
		if ( !isVectorLike( vec ) ) {
			throw new TypeError( format( 'invalid argument. First argument must be a one-dimensional ndarray. Value: `%s`.', vec ) );
		}
		if ( ndims !== void 0 && vec.shape[ 0 ] !== ndims ) {
			throw new Error( format( 'invalid argument. Vector length must match prototype dimensions. Expected: `%u`. Actual: `%u`.', ndims, vec.shape[ 0 ] ) );
		}
		if ( !isInteger( y ) ) {
			throw new TypeError( format( 'invalid argument. Second argument must be an integer representing the class label. Value: `%s`.', y ) );
		}

		vbuf = vec.data;
		sv = vec.strides[ 0 ];
		ov = vec.offset;

		if ( k > 0 && hasLabel( protoLabels, y, k ) ) {
			// Get buffer references and strides
			pbuf = protos.data;
			sp = protos.strides[ 0 ];

			// Find the closest prototype
			mini = closestPrototype( dist, k, ndims, pbuf, sp, 0, vbuf, sv, ov ); // eslint-disable-line max-len

			// Compute prototype buffer offset
			op = sp * mini;

			if ( getLabel( protoLabels, mini ) === y ) {
				lr = opts.learningRate; // correct: move towards
			} else {
				lr = -opts.learningRate; // incorrect: move away
			}

			// Update the closest prototype
			updatePrototype( ndims, pbuf, 1, op, vbuf, sv, ov, lr ); // Magic number `1` as we know that the matrix is row-major single-segment contiguous

			// Update the results object using dcopy (no dimensionality change)
			dcopy( protos.data.length, protos.data, 1, results.prototypes.data, 1 ); // eslint-disable-line max-len
			copyVector( results.labels, protoLabels );
		} else {
			// Set ndims if this is the first prototype
			if ( ndims === void 0 ) {
				ndims = vec.shape[ 0 ];
			}

			// Add new prototype for this label
			newData = addPrototype( k, ndims, protos, protoLabels, vec, y );
			protos = newData.protos;
			protoLabels = newData.protoLabels;
			k += 1;

			// Update the results object (dimensionality changed)
			results = createResults( k, ndims );
			copyMatrix( results.prototypes, protos );
			copyVector( results.labels, protoLabels );
		}

		// TODO: Is it required to maintain statistics just like in incr/kmeans?

		return results;
	}

	/**
	* Predicts class labels for data points.
	*
	* @private
	* @param {ndarray} [out] - output vector for storing predictions
	* @param {ndarray} X - matrix containing data points (`n x ndims`)
	* @throws {TypeError} output argument must be a vector
	* @throws {TypeError} must provide a matrix
	* @throws {Error} vector length must match number of data points
	* @throws {Error} number of matrix columns must match prototype dimensions
	* @returns {ndarray} vector containing predicted class labels
	*/
	function predict( out, X ) {
		var xbuf;
		var pbuf;
		var npts;
		var sx1;
		var sx2;
		var sp;
		var ox;
		var x;
		var o;
		var c;
		var i;

		if ( k === 0 ) {
			return null;
		}

		if ( arguments.length > 1 ) {
			if ( !isVectorLike( out ) ) {
				throw new TypeError( format( 'invalid argument. Output argument must be a one-dimensional ndarray. Value: `%s`.', out ) );
			}
			o = out;
			x = X;
		} else {
			x = out;
		}
		if ( !isMatrixLike( x ) ) {
			throw new TypeError( format( 'invalid argument. Must provide a two-dimensional ndarray. Value: `%s`.', x ) );
		}
		if ( x.shape[ 1 ] !== ndims ) {
			throw new Error( format( 'invalid argument. Number of matrix columns must match prototype dimensions. Expected: `%u`. Actual: `%u`.', ndims, x.shape[ 1 ] ) );
		}
		if ( o === void 0 ) {
			o = createIntVector( x.shape[ 0 ], false ); // high-level
		} else if ( o.shape[ 0 ] !== x.shape[ 0 ] ) {
			throw new Error( format( 'invalid argument. Output vector length must match the number of data points. Expected: `%u`. Actual: `%u`.', x.shape[ 0 ], o.shape[ 0 ] ) );
		}

		npts = x.shape[ 0 ];

		pbuf = protos.data;
		sp = protos.strides[ 0 ];

		xbuf = x.data;
		sx1 = x.strides[ 0 ];
		sx2 = x.strides[ 1 ];
		ox = x.offset;

		// For each data point, find the closest prototype and return its label
		for ( i = 0; i < npts; i++ ) {
			c = closestPrototype( dist, k, ndims, pbuf, sp, 0, xbuf, sx2, ox );

			// Set the predicted label (the label of the closest prototype)
			o.set( i, getLabel( protoLabels, c ) );

			// Move to next data point
			ox += sx1;
		}
		return o;
	}
}


// EXPORTS //

module.exports = incrlvq;
